# (1) Does the chi2 Weyl sum decay? Along real orbits, W_n(chi2,s=0)=(1/n) sum chi2(x_i).
def v2(n):
    k=0
    while n%2==0:n//=2;k+=1
    return k
def chi2(a): return 1 if a%3==1 else -1
import statistics
vals=[]
for x0 in range(1,200000,2):
    x=x0; s=0; n=0
    for _ in range(100000):
        if x==1: break
        y=3*x+1; b=v2(y); x=y//2**b
        s+=chi2(x); n+=1
    if n>50: vals.append(s/n)
print(f"orbits={len(vals)}  mean W_n(chi2,0)={statistics.mean(vals):+.4f}  (annealed E[(-1)^b]=-1/3={-1/3:+.4f})")
print("=> chi2 Weyl sum does NOT ->0; residues mod 3 are biased 1/3 : 2/3, NOT uniform.")
